def edit_distance_core(w1, w2):
    # Check if w2 can be obtained from w1 by one operation
    # 1. Delete a char from w1 to get w2
    # 2. Insert a char into w1 to get w2
    # 3. Replace a char in w1 to get w2
    # 4. Transpose adjacent chars in w1 to get w2

    len1, len2 = len(w1), len(w2)

    # Case 1: Delete one char from w1 -> w2
    # Means len1 == len2 + 1
    if len1 == len2 + 1:
        for i in range(len1):
            if w1[:i] + w1[i+1:] == w2:
                return True

    # Case 2: Insert one char into w1 -> w2
    # Means len2 == len1 + 1
    if len2 == len1 + 1:
        for i in range(len2):
            if w1 == w2[:i] + w2[i+1:]:
                return True

    # Case 3: Replace one char in w1 -> w2
    # Means len1 == len2
    if len1 == len2:
        diff = 0
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1

    # Case 4: Transpose adjacent chars in w1 -> w2
    # Means len1 == len2
    if len1 == len2:
        for i in range(len1 - 1):
            if w1[:i] + w1[i+1] + w1[i] + w1[i+2:] == w2:
                return True
        return False

    return False

