import sys

def get_core(word):
    """
    Extracts the core of a word:
    - Lowercase all alphabetic characters.
    - Remove any non-alphabetic characters.
    """
    result = []
    for char in word:
        if char.isalpha():
            result.append(char.lower())
    return ''.join(result)

def is_similar(c1, c2):
    """
    Checks if two word cores are similarly spelled.
    Conditions:
    - Single deletion
    - Single insertion
    - Single replacement
    - Single transposition of adjacent characters
    """
    # Filter out empty cores
    if not c1 or not c2:
        return False

    len1 = len(c1)
    len2 = len(c2)

    # Difference in length must be at most 1
    if abs(len1 - len2) > 1:
        return False

    # Helper to check single replacement
    def is_replace(s1, s2):
        if len(s1) != len(s2):
            return False
        diff = 0
        for ch1, ch2 in zip(s1, s2):
            if ch1 != ch2:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1

    # Helper to check single transposition
    def is_transpose(s1, s2):
        if len(s1) != len(s2):
            return False
        diff_count = 0
        i = 0
        while i < len(s1):
            if s1[i] != s2[i]:
                diff_count += 1
                if diff_count > 1:
                    return False
                # Swap s1[i] and s1[i+1] to see if it matches
                if i + 1 >= len(s1):
                    return False
                s1_list = list(s1)
                s1_list[i], s1_list[i+1] = s1_list[i+1], s1_list[i]
                s1 = ''.join(s1_list)
                break
            i += 1
        return s1 == s2

    # Helper to check single deletion/insertion
    def is_delete_insert(s1, s2):
        if len(s1) > len(s2):
            # Delete one char from s1 to get s2
            for i in range(len(s1)):
                if s1[:i] + s1[i+1:] == s2:
                    return True
            return False
        else:
            # Insert one char into s2 to get s1 (same as deleting from s1)
            for i in range(len(s2)):
                if s2[:i] + s2[i+1:] == s1:
                    return True
            return False

    if is_replace(c1, c2):
        return True
    if is_transpose(c1, c2):
        return True
    if is_delete_insert(c1, c2):
        return True

    return False

